var e=JSON.parse(`[{"id":"sa-bouillon-os-boeuf","name":"Bouillon d'os de bœuf et pied de veau","description":"La base de toute la cuisine maison : os de bœuf rôtis et pied de veau mijotés 10 h, pour un bouillon ambré qui prend en gelée au frais. À boire en tasse ou à utiliser dans les soupes et sauces.","emoji":"🦴","category":"soupe","mealTypes":["dejeuner","diner","collation"],"cuisine":"rustique","prepTime":20,"cookTime":600,"difficulty":"tres-facile","servings":8,"ingredients":[{"id":"os-boeuf","qty":2500,"unit":"g","note":"os à moelle, jarret, genou, queue : un mélange"},{"id":"pied-veau","qty":500,"unit":"g","note":"coupé en morceaux par le boucher"},{"id":"carotte","qty":2,"unit":"piece","note":"en tronçons"},{"id":"oignon","qty":2,"unit":"piece","note":"coupés en deux, avec la peau"},{"id":"poireau","qty":1,"unit":"piece","note":"le vert surtout"},{"id":"celeri-branche","qty":2,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse","note":"écrasées"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"vinaigre-cidre","qty":30,"unit":"ml"},{"id":"eau","qty":4000,"unit":"ml","note":"froide"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":4,"unit":"brin"},{"id":"poivre","qty":1,"unit":"cac","note":"en grains"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 220 °C. Étalez les os sur une plaque, badigeonnez-les de concentré de tomate et rôtissez 40 min en les retournant à mi-cuisson : ils doivent être bien dorés, presque acajou.","Blanchissez le pied de veau : plongez-le 5 min dans l'eau bouillante, égouttez et rincez à l'eau froide pour retirer les impuretés.","Mettez os rôtis et pied de veau dans un grand faitout (8 L), couvrez avec les 4 L d'eau froide et le vinaigre. Laissez reposer 30 min hors du feu : l'acidité aide à extraire minéraux et collagène.","Déglacez la plaque du four avec un peu d'eau chaude en grattant les sucs, et versez ce jus dans le faitout.","Portez doucement à frémissement à feu moyen. Écumez soigneusement la mousse grise pendant les 15 premières minutes.","Ajoutez légumes, ail, thym, laurier et poivre. Baissez à feu très doux : la surface doit à peine trembler (1 bulle toutes les 2 s). Laissez cuire 8 à 10 h à demi couvert, en complétant avec de l'eau chaude si les os se découvrent.","Filtrez à travers une passoire fine tapissée d'une étamine. Salez légèrement seulement au moment d'utiliser.","Laissez refroidir puis réfrigérez une nuit : retirez la couche de graisse figée (gardez-la pour rôtir des pommes de terre). Le bouillon doit être pris en gelée tremblotante."],"tags":["riche en collagène","batch cooking","préparation à l’avance","économique","sans gluten","mijoté"],"seasons":[],"technique":"mijote","flavors":["umami","reconfortant"],"tips":"Se conserve 5 jours au réfrigérateur, 6 mois au congélateur en bocaux ou en bacs à glaçons (pratique pour déglacer). Rendement : environ 2 L."},{"id":"sa-bouillon-volaille-maison","name":"Bouillon de volaille maison aux ailes et carcasses","description":"Un fond blanc doré et parfumé, fait avec carcasses et ailes de poulet, légumes et bouquet garni. Les ailes, effilochées, se mangent dans le bouillon ou dans une salade.","emoji":"🍲","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":240,"difficulty":"tres-facile","servings":8,"ingredients":[{"id":"carcasse-poulet","qty":4,"unit":"piece","note":"crues, avec quelques pattes si possible"},{"id":"poulet-aile","qty":10,"unit":"piece"},{"id":"carotte","qty":2,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece","note":"piqué d'un clou de girofle"},{"id":"poireau","qty":1,"unit":"piece"},{"id":"celeri-branche","qty":2,"unit":"piece"},{"id":"girofle","qty":1,"unit":"pincee"},{"id":"vinaigre-cidre","qty":15,"unit":"ml"},{"id":"eau","qty":3500,"unit":"ml","note":"froide"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"persil","qty":6,"unit":"brin","note":"les queues"},{"id":"poivre","qty":1,"unit":"cac","note":"en grains"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Rincez les carcasses à l'eau froide et cassez-les en 2 ou 3 morceaux avec un couperet pour exposer les os.","Placez carcasses et ailes dans un faitout, couvrez d'eau froide, ajoutez le vinaigre et portez à frémissement à feu moyen (environ 20 min).","Écumez la mousse pendant 10 min jusqu'à ce que la surface soit claire.","Ajoutez légumes en gros morceaux, oignon piqué, bouquet de thym, laurier, queues de persil et poivre. Laissez frémir à feu très doux 3 h 30, sans couvercle et sans jamais faire bouillir (sinon le bouillon se trouble).","Au bout de 1 h, retirez 4 ailes, effilochez leur chair et remettez les os dans le faitout ; gardez la chair au frais.","Filtrez au chinois fin, laissez refroidir à température ambiante 1 h puis au réfrigérateur. Dégraissez le lendemain en retirant la graisse figée.","Pour servir en soupe : réchauffez 300 ml de bouillon par personne, salez, ajoutez la chair effilochée des ailes et un peu de persil ciselé."],"tags":["riche en collagène","batch cooking","économique","préparation à l’avance","sans gluten"],"seasons":[],"technique":"mijote","flavors":["umami","reconfortant","herbace"],"tips":"Rendement : environ 2,5 L. Réfrigérateur 4 jours, congélateur 6 mois. Une carcasse de poulet rôti du dimanche fait aussi l'affaire."},{"id":"sa-soupe-oignon-gratinee","name":"Soupe à l'oignon gratinée au comté","description":"Oignons caramélisés 45 min dans le beurre, mouillés au vin blanc et au bouillon de bœuf maison, sous un épais couvercle de pain au levain et de comté gratiné.","emoji":"🧅","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":70,"difficulty":"facile","servings":2,"ingredients":[{"id":"oignon","qty":600,"unit":"g","note":"émincés finement"},{"id":"beurre","qty":40,"unit":"g"},{"id":"farine","qty":1,"unit":"cas"},{"id":"vin-blanc","qty":120,"unit":"ml"},{"id":"bouillon-boeuf","qty":1000,"unit":"ml"},{"id":"pain-levain","qty":4,"unit":"tranche","note":"épaisses, rassises"},{"id":"comte","qty":130,"unit":"g","note":"râpé"},{"id":"thym","qty":2,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites fondre le beurre dans une cocotte à fond épais à feu moyen. Ajoutez les oignons et 1 pincée de sel, mélangez pour bien les enrober.","Laissez cuire 45 min à feu moyen-doux en remuant toutes les 5 min et en grattant le fond : les oignons doivent devenir fondants puis d'un brun acajou uniforme. S'ils accrochent, ajoutez 2 c. à soupe d'eau.","Saupoudrez de farine, mélangez 1 min, puis versez le vin blanc et grattez les sucs. Laissez réduire 2 min.","Ajoutez le bouillon, le thym et le laurier. Laissez mijoter 20 min à petits frémissements. Salez, poivrez.","Pendant ce temps, faites griller les tranches de pain 3 min de chaque côté sous le gril du four.","Préchauffez le gril à 240 °C. Versez la soupe dans 2 bols allant au four, posez 2 tranches de pain par bol, couvrez généreusement de comté jusqu'aux bords.","Enfournez 6 à 8 min, en haut du four, jusqu'à ce que le fromage bouillonne et soit doré par endroits. Servez brûlant."],"tags":["réconfortant","four","économique","calorique","week-end"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","reconfortant","lacte"],"tips":"La base d'oignons caramélisés se prépare à l'avance et se congèle ; il suffit ensuite de mouiller au bouillon."},{"id":"sa-garbure-bearnaise","name":"Garbure béarnaise au confit de canard","description":"La soupe-repas du Béarn : chou, pommes de terre, fèves et poireaux longuement mijotés avec talon de jambon, puis couronnés de cuisses de canard confites. On y fait « chabrot » avec un peu de vin.","emoji":"🥬","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"canard-cuisse","qty":4,"unit":"piece","note":"cuisses confites"},{"id":"jambon-cru","qty":80,"unit":"g","note":"talon de jambon de Bayonne, en dés"},{"id":"chou-vert","qty":500,"unit":"g","note":"chou frisé, en lanières"},{"id":"pomme-de-terre","qty":700,"unit":"g","note":"en gros morceaux"},{"id":"feves","qty":200,"unit":"g","note":"écossées, fraîches ou surgelées"},{"id":"poireau","qty":2,"unit":"piece","note":"en rondelles"},{"id":"navet","qty":2,"unit":"piece","note":"en quartiers"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"graisse-canard","qty":30,"unit":"g","note":"prélevée sur le confit"},{"id":"bouillon-volaille","qty":1800,"unit":"ml"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans un grand faitout, faites fondre la graisse de canard à feu moyen. Faites revenir l'oignon émincé et les dés de jambon 5 min jusqu'à ce que l'oignon soit translucide.","Ajoutez poireaux et navets, faites suer 5 min en remuant, puis versez le bouillon. Ajoutez ail écrasé, thym, laurier et portez à ébullition.","Plongez les pommes de terre et laissez frémir 20 min à feu moyen-doux.","Ajoutez le chou en lanières et les fèves, poursuivez 40 min à petits bouillons : le chou doit être fondant et les pommes de terre commencer à s'écraser pour lier la soupe.","Pendant ce temps, faites dorer les cuisses de canard côté peau dans une poêle sèche 8 min à feu moyen, puis 3 min côté chair : la peau doit être croustillante.","Écrasez grossièrement quelques morceaux de pomme de terre contre la paroi pour épaissir. Assaisonnez avec sel, poivre et piment d'Espelette.","Servez dans des assiettes creuses, une cuisse de canard posée sur chaque portion. Le dernier fond de bouillon se boit traditionnellement avec un trait de vin rouge (le chabrot)."],"tags":["réconfortant","mijoté","familial","prise de masse","week-end","calorique"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["reconfortant","umami"],"tips":"Encore meilleure le lendemain, quand elle a épaissi : la garbure doit presque tenir la cuillère debout."},{"id":"sa-potee-auvergnate","name":"Potée auvergnate au jarret et saucisse de Morteau","description":"Le pot-au-feu du cochon : jambonneau demi-sel, saucisse fumée et légumes d'hiver mijotés ensemble, servis avec leur bouillon, de la moutarde et des cornichons.","emoji":"🥘","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":165,"difficulty":"facile","servings":4,"ingredients":[{"id":"porc-jarret","qty":1000,"unit":"g","note":"jambonneau demi-sel, dessalé 2 h"},{"id":"saucisse-morteau","qty":1,"unit":"piece"},{"id":"chou-vert","qty":1,"unit":"piece","note":"chou de Milan, en quartiers"},{"id":"pomme-de-terre","qty":800,"unit":"g","note":"fermes, épluchées"},{"id":"carotte","qty":4,"unit":"piece"},{"id":"navet","qty":3,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece","note":"piqué de 2 clous de girofle"},{"id":"girofle","qty":2,"unit":"pincee"},{"id":"eau","qty":3000,"unit":"ml"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"moutarde","qty":4,"unit":"cac","note":"pour servir"},{"id":"cornichon","qty":80,"unit":"g","note":"pour servir"},{"id":"poivre","qty":1,"unit":"cac","note":"en grains"}],"steps":["Mettez le jambonneau dessalé dans un grand faitout, couvrez d'eau froide, portez à ébullition et écumez 5 min.","Ajoutez l'oignon piqué, le thym, le laurier et le poivre en grains. Laissez frémir à couvert 1 h 30 à feu doux. Ne salez pas : le jambonneau est déjà salé.","Pendant ce temps, blanchissez les quartiers de chou 5 min dans une casserole d'eau bouillante, égouttez : cela le rend plus digeste.","Ajoutez au faitout carottes, navets et chou. Poursuivez 30 min à frémissement.","Piquez la saucisse de Morteau en 3 endroits et plongez-la avec les pommes de terre. Cuisez encore 35 min : la pointe d'un couteau doit traverser les pommes de terre sans résistance.","Sortez viande et saucisse, tranchez-les. Goûtez le bouillon et rectifiez.","Servez dans de grandes assiettes creuses : légumes et viandes, une louche de bouillon brûlant par-dessus, avec moutarde et cornichons à côté."],"tags":["mijoté","familial","réconfortant","batch cooking","sans gluten","riche en protéines"],"seasons":["hiver"],"technique":"bouilli","flavors":["fume","reconfortant","umami"],"tips":"Le bouillon restant, dégraissé, fait une excellente base pour une soupe de lentilles ou de pois."},{"id":"sa-veloute-potimarron-chataignes","name":"Velouté de potimarron, châtaignes, lardons et œufs mollets","description":"Un velouté d'automne soyeux et légèrement sucré, relevé de lardons croustillants, de châtaignes rôties au beurre et d'un œuf mollet qui coule dans l'assiette.","emoji":"🎃","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"potimarron","qty":700,"unit":"g","note":"avec la peau, épépiné, en cubes"},{"id":"chataigne","qty":150,"unit":"g","note":"cuites sous vide"},{"id":"lardons","qty":160,"unit":"g","note":"fumés"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"beurre","qty":30,"unit":"g"},{"id":"bouillon-volaille","qty":700,"unit":"ml"},{"id":"creme-fraiche","qty":80,"unit":"ml"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"ciboulette","qty":1,"unit":"botte","optional":true},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites fondre 20 g de beurre dans une casserole à feu moyen et faites suer l'oignon émincé 4 min sans coloration.","Ajoutez le potimarron et 100 g de châtaignes, mélangez 2 min, puis versez le bouillon. Portez à ébullition et laissez cuire 20 min à feu moyen, à couvert : la courge doit s'écraser sous la fourchette.","Pendant ce temps, plongez les œufs dans une casserole d'eau bouillante et cuisez exactement 6 min, puis refroidissez-les 2 min dans de l'eau glacée et écalez-les délicatement.","Dans une poêle sèche, faites dorer les lardons 6 min à feu moyen jusqu'à ce qu'ils soient croustillants. Égouttez-les, puis faites rissoler les 50 g de châtaignes restantes, émiettées, 3 min dans la graisse rendue avec le reste du beurre.","Mixez la soupe avec la crème et la muscade jusqu'à obtenir un velouté lisse (2 min au mixeur plongeant). Salez, poivrez ; allongez d'un peu de bouillon s'il est trop épais.","Réchauffez les œufs 1 min dans de l'eau chaude du robinet. Versez le velouté dans des bols, ajoutez 2 œufs par bol, les lardons, les châtaignes rôties et la ciboulette ciselée."],"tags":["réconfortant","riche en protéines","sans gluten","familial"],"seasons":["automne","hiver"],"technique":"mixe","flavors":["cremeux","sucre","fume"],"tips":"Le velouté seul se congèle très bien ; préparez les garnitures au dernier moment."},{"id":"sa-bouillabaisse-simplifiee","name":"Bouillabaisse simplifiée et sa rouille","description":"Une bouillabaisse du quotidien : bouillon safrané au fenouil et à la tomate, rouget, lotte, dorade et gambas pochés à la minute, pommes de terre fondantes et rouille maison sur croûtons.","emoji":"🐟","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":35,"cookTime":45,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"lotte","qty":400,"unit":"g","note":"en tronçons de 4 cm"},{"id":"rouget","qty":4,"unit":"piece","note":"en filets"},{"id":"bar","qty":1,"unit":"piece","note":"ou dorade, en filets, arêtes gardées"},{"id":"crevette","qty":12,"unit":"piece","note":"gambas crues"},{"id":"fumet-poisson","qty":1200,"unit":"ml"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"en rondelles de 1 cm"},{"id":"fenouil","qty":1,"unit":"piece","note":"émincé"},{"id":"tomate","qty":3,"unit":"piece","note":"concassées"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"safran","qty":2,"unit":"pincee"},{"id":"orange","qty":1,"unit":"piece","note":"1 lanière de zeste"},{"id":"huile-olive","qty":120,"unit":"ml","note":"dont 80 ml pour la rouille"},{"id":"jaune-oeuf","qty":1,"unit":"piece"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"pain-levain","qty":8,"unit":"tranche","note":"fines, grillées"},{"id":"thym","qty":2,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Dans une grande cocotte, chauffez 40 ml d'huile d'olive à feu moyen. Faites revenir oignon et fenouil émincés 6 min, ajoutez 3 gousses d'ail écrasées, les tomates, le thym et le zeste d'orange, puis cuisez 5 min.","Versez le fumet et 1 pincée de safran, ajoutez les arêtes du bar, portez à ébullition franche et laissez bouillir 15 min à gros bouillons : c'est ce qui émulsionne l'huile et donne le bouillon lié typique.","Préparez la rouille : écrasez 2 gousses d'ail avec 1 pincée de sel, ajoutez le jaune, le piment et 1 pincée de safran, puis montez avec 80 ml d'huile versée en filet en fouettant, comme une mayonnaise.","Retirez les arêtes du bouillon, ajoutez les rondelles de pomme de terre et cuisez 15 min à feu moyen : elles doivent être tendres à la pointe du couteau.","Ajoutez la lotte, cuisez 4 min à frémissement ; puis les filets de rouget et de bar côté peau dessus et les gambas, et cuisez encore 3 min sans remuer : la chair des filets devient nacrée et les gambas rosées.","Servez le bouillon et les pommes de terre dans des assiettes creuses, les poissons à côté sur un plat, avec les croûtons tartinés de rouille."],"tags":["week-end","riche en protéines","familial","calorique"],"seasons":["ete","automne"],"technique":"bouilli","flavors":["iode","epice","umami"],"tips":"Demandez à votre poissonnier les têtes et arêtes : 15 min de cuisson en plus avec elles donnent un bouillon encore plus profond."},{"id":"sa-chaudree-haddock-palourdes","name":"Chaudrée de haddock et palourdes au bacon","description":"Le chowder de Nouvelle-Angleterre : une soupe crémeuse au lait entier, pommes de terre fondantes, bacon fumé, haddock en gros flocons et palourdes ouvertes à la vapeur.","emoji":"🥣","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"americaine","prepTime":20,"cookTime":35,"difficulty":"facile","servings":4,"ingredients":[{"id":"haddock","qty":400,"unit":"g","note":"en gros morceaux"},{"id":"palourde","qty":800,"unit":"g","note":"dégorgées 1 h dans l'eau salée"},{"id":"bacon","qty":8,"unit":"piece","note":"en lardons"},{"id":"pomme-de-terre","qty":700,"unit":"g","note":"en dés de 1,5 cm"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"en dés"},{"id":"beurre","qty":30,"unit":"g"},{"id":"farine","qty":2,"unit":"cas"},{"id":"lait","qty":700,"unit":"ml"},{"id":"creme-liquide","qty":150,"unit":"ml"},{"id":"vin-blanc","qty":100,"unit":"ml"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"thym","qty":2,"unit":"brin"},{"id":"ciboulette","qty":1,"unit":"botte"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites ouvrir les palourdes avec le vin blanc dans une cocotte couverte à feu vif, 4 min en secouant. Retirez-les, décortiquez la moitié, et filtrez le jus de cuisson à travers un papier absorbant.","Dans la même cocotte rincée, faites dorer le bacon 5 min à feu moyen. Ajoutez le beurre, l'oignon et le céleri, faites suer 5 min.","Saupoudrez de farine et remuez 1 min pour former un roux blond.","Versez progressivement le lait en fouettant, puis le jus des palourdes. Ajoutez pommes de terre, thym et laurier. Laissez frémir 15 min à feu doux sans bouillir, en remuant de temps en temps : la soupe épaissit et nappe la cuillère.","Ajoutez la crème et le haddock, cuisez 5 min à frémissement : le poisson doit se détacher en gros flocons.","Remettez toutes les palourdes 1 min pour les réchauffer. Poivrez (le haddock et le bacon salent déjà assez) et parsemez de ciboulette ciselée."],"tags":["réconfortant","riche en protéines","familial","calorique"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["cremeux","fume","iode"],"tips":"Accompagnez de crackers ou de pain grillé. Ne laissez jamais bouillir après l'ajout du lait, sinon il tranche."},{"id":"sa-avgolemono-poulet","name":"Avgolemono : soupe grecque au poulet, riz, œuf et citron","description":"Le réconfort grec : un bouillon de volaille lié à l'œuf et au citron, velouté et acidulé, avec du riz fondant et des hauts de cuisse effilochés.","emoji":"🍋","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":10,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"poulet-haut-cuisse-desosse","qty":350,"unit":"g"},{"id":"bouillon-volaille","qty":1200,"unit":"ml"},{"id":"riz-blanc","qty":110,"unit":"g","note":"grain long"},{"id":"oeuf","qty":3,"unit":"piece","note":"à température ambiante"},{"id":"citron","qty":2,"unit":"piece","note":"jus"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"aneth","qty":10,"unit":"g"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Portez le bouillon à frémissement avec le laurier. Pochez les hauts de cuisse 20 min à feu doux, puis sortez-les et effilochez-les à la fourchette.","Versez le riz dans le bouillon frémissant et cuisez 15 min à feu moyen : il doit être bien tendre. Retirez le laurier et baissez au plus doux.","Dans un saladier, fouettez énergiquement les œufs 1 min jusqu'à ce qu'ils moussent, puis ajoutez le jus de citron en fouettant.","Tempérez : versez une louche de bouillon chaud en filet très fin sur les œufs en fouettant sans arrêt, puis une deuxième louche.","Hors du feu, reversez le mélange dans la casserole en remuant. Remettez sur feu très doux 2 à 3 min en remuant : la soupe épaissit et devient opaque et soyeuse. Elle ne doit surtout pas bouillir, sinon l'œuf graine.","Ajoutez le poulet effiloché, salez, poivrez. Servez avec un filet d'huile d'olive et l'aneth ciselé."],"tags":["réconfortant","riche en protéines","sans gluten","rapide","familial"],"seasons":[],"technique":"poche","flavors":["acidule","cremeux","reconfortant"],"tips":"Pour réchauffer, chauffez doucement sans faire bouillir. Le riz absorbe le bouillon : allongez avec un peu d'eau chaude le lendemain."},{"id":"sa-harira-agneau","name":"Harira marocaine à l'agneau","description":"La soupe de rupture du jeûne : agneau fondant, tomate, lentilles et pois chiches en quantité raisonnable, herbes fraîches et épices chaudes, liée d'un filet de farine et servie avec des dattes.","emoji":"🍲","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"nord-africaine","prepTime":25,"cookTime":90,"difficulty":"facile","servings":4,"ingredients":[{"id":"agneau-epaule","qty":650,"unit":"g","note":"en petits dés de 1,5 cm"},{"id":"lentilles-vertes","qty":70,"unit":"g","note":"rincées"},{"id":"pois-chiches","qty":150,"unit":"g","note":"cuits, pelés si possible"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"oignon","qty":1,"unit":"piece","note":"râpé"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"avec les feuilles, hachées"},{"id":"pates","qty":60,"unit":"g","note":"vermicelles cassés"},{"id":"farine","qty":2,"unit":"cas"},{"id":"beurre-clarifie","qty":20,"unit":"g","note":"ou smen"},{"id":"bouillon-boeuf","qty":1500,"unit":"ml","note":"ou eau"},{"id":"ras-el-hanout","qty":1,"unit":"cac"},{"id":"curcuma","qty":1,"unit":"cac"},{"id":"gingembre","qty":10,"unit":"g","note":"râpé"},{"id":"cannelle","qty":1,"unit":"pincee"},{"id":"coriandre","qty":20,"unit":"g"},{"id":"persil","qty":20,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"en quartiers"},{"id":"datte","qty":8,"unit":"piece","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper les lentilles 12 h (une nuit) dans de l’eau tiède, jetez l’eau et rincez avant de cuire.","Dans un faitout, faites fondre le beurre clarifié à feu moyen-vif et faites revenir l'agneau 5 min jusqu'à ce qu'il soit doré. Ajoutez l'oignon râpé, le céleri, le gingembre, le curcuma, le ras-el-hanout, la cannelle et la moitié des herbes hachées ; remuez 2 min.","Ajoutez les tomates concassées, le concentré, les lentilles et le bouillon. Portez à ébullition, puis laissez mijoter à couvert 1 h à feu doux.","Ajoutez les pois chiches et les vermicelles, cuisez 10 min à feu moyen.","Délayez la farine dans 150 ml d'eau froide jusqu'à ce qu'il n'y ait plus de grumeaux. Versez en filet dans la soupe en remuant sans arrêt, puis laissez frémir 5 min : la harira devient veloutée et nappante.","Ajoutez le reste des herbes hachées, salez, poivrez largement.","Servez bien chaud avec des quartiers de citron à presser et des dattes à côté."],"tags":["réconfortant","riche en protéines","batch cooking","familial","mijoté","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","herbace","reconfortant"],"tips":"Se garde 4 jours au frais et se congèle ; elle épaissit en refroidissant, allongez-la avec un peu de bouillon.","restTime":720},{"id":"sa-caldo-verde-chorizo","name":"Caldo verde au chorizo","description":"La soupe nationale portugaise : un bouillon velouté de pommes de terre écrasées, de fines lanières de chou frisé et de rondelles de chorizo grillées, avec un filet d'huile d'olive.","emoji":"🥬","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"portugaise","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"pomme-de-terre-farineuse","qty":600,"unit":"g","note":"en morceaux"},{"id":"chou-vert","qty":200,"unit":"g","note":"chou frisé ou kale, en très fines lanières"},{"id":"chorizo","qty":140,"unit":"g","note":"en rondelles"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"bouillon-volaille","qty":1000,"unit":"ml"},{"id":"pain-levain","qty":2,"unit":"tranche","note":"pour servir (broa de maïs si possible)"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Chauffez 2 c. à soupe d'huile d'olive dans une casserole à feu moyen. Faites suer l'oignon émincé et l'ail 5 min sans coloration.","Ajoutez les pommes de terre et le bouillon, portez à ébullition et cuisez 20 min à feu moyen, jusqu'à ce qu'elles se défassent.","Pendant ce temps, faites griller les rondelles de chorizo dans une poêle sèche 3 min à feu moyen, jusqu'à ce qu'elles rendent leur huile rouge et soient légèrement croustillantes.","Écrasez les pommes de terre au presse-purée directement dans la casserole (ou mixez la moitié) pour obtenir un bouillon épais.","Ajoutez le chou en lanières et la moitié du chorizo avec son huile ; cuisez 5 min à frémissement : le chou doit rester vert vif et légèrement croquant.","Salez, poivrez, servez avec le reste de chorizo dessus, un filet d'huile d'olive crue et le pain."],"tags":["rapide","économique","réconfortant","calorique"],"seasons":["automne","hiver"],"technique":"bouilli","flavors":["fume","reconfortant","piquant"],"tips":"Le secret : couper le chou en chiffonnade très fine (roulez les feuilles en cigare et taillez en fils de 2 mm)."},{"id":"sa-sopa-de-ajo","name":"Sopa de ajo castillane aux œufs et jambon","description":"La soupe à l'ail des bergers castillans : pain rassis rissolé à l'huile d'olive et au pimentón, ail doré, jambon serrano, bouillon et œufs pochés directement dans la soupe.","emoji":"🧄","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"espagnole","prepTime":10,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"ail","qty":10,"unit":"gousse","note":"en fines lamelles"},{"id":"pain-levain","qty":120,"unit":"g","note":"rassis, en fines tranches"},{"id":"jambon-cru","qty":5,"unit":"piece","note":"serrano, en lanières"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"huile-olive","qty":4,"unit":"cas"},{"id":"paprika","qty":2,"unit":"cac","note":"pimentón de la Vera, doux ou fumé"},{"id":"bouillon-volaille","qty":1000,"unit":"ml"},{"id":"cumin","qty":1,"unit":"pincee","optional":true},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Dans une cocotte en terre ou en fonte, chauffez l'huile d'olive à feu moyen-doux. Faites dorer l'ail 3 min en remuant : il doit être blond, jamais brun (sinon il devient amer).","Ajoutez le jambon et le pain, faites-les rissoler 4 min en remuant pour qu'ils s'imbibent d'huile et dorent légèrement.","Retirez du feu, saupoudrez de paprika (et de cumin) et mélangez 20 s : hors du feu, le paprika ne brûle pas.","Versez immédiatement le bouillon chaud, portez à frémissement et laissez cuire 12 min à feu doux : le pain se délite et épaissit la soupe.","Salez si besoin. Cassez les œufs un à un à la surface de la soupe frémissante, couvrez et pochez 3 à 4 min : les blancs doivent être pris, les jaunes encore coulants.","Parsemez de persil et servez dans la cocotte, en servant 2 œufs par personne."],"tags":["rapide","économique","réconfortant","une poêle"],"seasons":["automne","hiver","printemps"],"technique":"poche","flavors":["reconfortant","fume","umami"],"tips":"Le meilleur usage pour un pain au levain de 3 jours. On peut aussi gratiner les œufs 3 min sous le gril."},{"id":"sa-minestrone-pancetta","name":"Minestrone à la pancetta et croûte de parmesan","description":"Une minestrone épaisse et généreuse : légumes de saison, pancetta rissolée, haricots blancs, petites pâtes et une croûte de parmesan qui fond dans le bouillon. Finie au pesto improvisé au basilic.","emoji":"🥣","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":45,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"pancetta","qty":130,"unit":"g","note":"en dés"},{"id":"haricots-blancs","qty":150,"unit":"g","note":"cuits, égouttés"},{"id":"pates","qty":100,"unit":"g","note":"petites pâtes (ditalini)"},{"id":"courgette","qty":1,"unit":"piece","note":"en dés"},{"id":"carotte","qty":1,"unit":"piece","note":"en dés"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"en dés"},{"id":"haricots-verts","qty":100,"unit":"g","note":"en tronçons"},{"id":"tomates-concassees","qty":200,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"parmesan","qty":60,"unit":"g","note":"dont 1 croûte"},{"id":"bouillon-volaille","qty":1000,"unit":"ml"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"basilic","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une cocotte, faites rissoler la pancetta dans 1 c. à soupe d'huile 5 min à feu moyen. Ajoutez oignon, carotte et céleri (le soffritto) et faites suer 8 min en remuant.","Ajoutez 1 gousse d'ail hachée, les tomates, le bouillon et la croûte de parmesan. Portez à ébullition puis laissez frémir 15 min à feu moyen-doux.","Ajoutez la courgette, les haricots verts et les haricots blancs, poursuivez 10 min.","Versez les pâtes et cuisez le temps indiqué sur le paquet moins 1 min (environ 9 min), en remuant de temps en temps pour qu'elles n'attachent pas.","Pendant ce temps, pilez ou hachez finement le basilic avec la gousse d'ail restante, 2 c. à soupe d'huile d'olive et 1 pincée de sel.","Retirez la croûte de parmesan, salez, poivrez. Servez chaque bol avec 1 cuillère d'huile au basilic et le parmesan râpé."],"tags":["familial","économique","batch cooking","réconfortant"],"seasons":["printemps","ete","automne"],"technique":"mijote","flavors":["herbace","umami"],"tips":"Pour la lunch box, cuisez les pâtes à part : elles ne gonfleront pas dans le bouillon."},{"id":"sa-soupe-miso-saumon-udon","name":"Soupe miso au saumon, udon et shiitakés","description":"Un bol japonais complet : dashi au miso, nouilles udon épaisses, pavé de saumon poché, pak choï, shiitakés et nori. Prêt en 25 minutes.","emoji":"🍜","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"japonaise","prepTime":10,"cookTime":15,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saumon","qty":2,"unit":"piece","note":"pavés sans peau, coupés en 4"},{"id":"udon","qty":300,"unit":"g","note":"fraîches"},{"id":"dashi","qty":1000,"unit":"ml"},{"id":"miso","qty":50,"unit":"g","note":"miso blanc ou rouge"},{"id":"chou-chinois","qty":200,"unit":"g","note":"pak choï, coupé en deux"},{"id":"champignon-forestier","qty":100,"unit":"g","note":"shiitakés émincés"},{"id":"oignon-nouveau","qty":2,"unit":"piece"},{"id":"gingembre","qty":10,"unit":"g","note":"en julienne"},{"id":"sauce-soja","qty":15,"unit":"ml"},{"id":"algue-nori","qty":1,"unit":"piece","note":"en lanières"},{"id":"sesame","qty":1,"unit":"cac"}],"steps":["Portez le dashi à frémissement avec le gingembre et la sauce soja. Ajoutez les shiitakés et cuisez 3 min.","Plongez les morceaux de saumon et le pak choï, pochez 4 min à frémissement très doux : le saumon doit rester rosé à cœur.","Pendant ce temps, cuisez les udon 2 à 3 min dans une casserole d'eau bouillante, égouttez et répartissez dans 2 grands bols.","Coupez le feu sous le bouillon. Délayez le miso dans une louche de bouillon chaud, puis reversez dans la casserole : le miso ne doit jamais bouillir, il perdrait ses arômes et ses ferments.","Disposez saumon, pak choï et champignons sur les nouilles, versez le bouillon brûlant.","Parsemez d'oignon nouveau émincé, de sésame et de nori, et servez aussitôt."],"tags":["rapide","riche en protéines","fermenté","léger","sportif"],"seasons":[],"technique":"poche","flavors":["umami","iode"],"tips":"Remplacez les udon par des nouilles soba ou du riz pour varier. Ajoutez un œuf mollet pour encore plus de protéines."},{"id":"sa-pho-bo","name":"Phở bò au bœuf cru et bouillon épicé","description":"La grande soupe vietnamienne : bouillon de bœuf infusé à l'anis étoilé, cannelle et oignon brûlé, nouilles de riz, fines tranches de bœuf cuites par le bouillon brûlant, herbes fraîches et citron vert.","emoji":"🍜","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"thai-vietnamienne","prepTime":20,"cookTime":40,"difficulty":"facile","servings":2,"ingredients":[{"id":"bouillon-boeuf","qty":1500,"unit":"ml","note":"bouillon d'os maison"},{"id":"boeuf-rosbif","qty":280,"unit":"g","note":"filet ou tende de tranche, très froid"},{"id":"nouilles-riz","qty":160,"unit":"g","note":"larges (banh pho)"},{"id":"oignon","qty":1,"unit":"piece","note":"coupé en deux"},{"id":"gingembre","qty":30,"unit":"g","note":"coupé en deux dans la longueur"},{"id":"girofle","qty":3,"unit":"pincee","note":"2 anis étoilés + 2 clous de girofle"},{"id":"cannelle","qty":1,"unit":"pincee","note":"1 petit bâton"},{"id":"coriandre-graines","qty":1,"unit":"cac"},{"id":"sauce-poisson","qty":30,"unit":"ml"},{"id":"sucre","qty":1,"unit":"cac"},{"id":"oignon-nouveau","qty":3,"unit":"piece"},{"id":"coriandre","qty":15,"unit":"g"},{"id":"basilic","qty":10,"unit":"g","note":"basilic thaï"},{"id":"citron-vert","qty":1,"unit":"piece","note":"en quartiers"},{"id":"piment-frais","qty":1,"unit":"piece","note":"en rondelles"}],"steps":["Faites noircir l'oignon et le gingembre côté coupé directement sur la flamme ou dans une poêle sèche à feu vif, 5 min : ils doivent être bien charbonnés en surface.","Toastez l'anis, le girofle, la cannelle et les graines de coriandre 1 min dans une casserole sèche jusqu'à ce qu'ils sentent fort.","Ajoutez le bouillon, l'oignon et le gingembre brûlés, la sauce poisson et le sucre. Laissez frémir 30 min à feu doux, à couvert, puis filtrez.","Placez le bœuf 15 min au congélateur, puis tranchez-le le plus finement possible (2 mm), contre le sens des fibres.","Réhydratez les nouilles selon le paquet (en général 4 min dans l'eau bouillante), égouttez et répartissez dans 2 grands bols.","Portez le bouillon à forte ébullition. Disposez les tranches de bœuf crues en une seule couche sur les nouilles et versez le bouillon bouillant directement dessus : la viande cuit instantanément et devient rosée.","Garnissez d'oignon nouveau, coriandre, basilic thaï et piment ; chacun presse son citron vert à table."],"tags":["riche en protéines","sans gluten","sportif","riche en collagène"],"seasons":[],"technique":"bouilli","flavors":["epice","herbace","umami"],"tips":"Le bouillon parfumé se prépare en grande quantité et se congèle : le phở devient alors un repas de 10 minutes."},{"id":"sa-tom-kha-gai","name":"Tom kha gai au poulet et lait de coco","description":"La soupe thaïe crémeuse au lait de coco, citronnelle, gingembre et citron vert, avec hauts de cuisse de poulet tendres et champignons. Servie avec du riz jasmin pour un vrai repas.","emoji":"🥥","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"thai-vietnamienne","prepTime":15,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"poulet-haut-cuisse-desosse","qty":350,"unit":"g","note":"en lanières"},{"id":"lait-coco","qty":400,"unit":"ml"},{"id":"bouillon-volaille","qty":500,"unit":"ml"},{"id":"citronnelle","qty":2,"unit":"piece","note":"écrasées, en tronçons"},{"id":"gingembre","qty":30,"unit":"g","note":"ou galanga, en rondelles"},{"id":"champignon","qty":150,"unit":"g","note":"émincés"},{"id":"tomate-cerise","qty":8,"unit":"piece","note":"coupées en deux"},{"id":"sauce-poisson","qty":30,"unit":"ml"},{"id":"citron-vert","qty":2,"unit":"piece"},{"id":"piment-frais","qty":1,"unit":"piece"},{"id":"sucre","qty":1,"unit":"cac"},{"id":"coriandre","qty":15,"unit":"g"},{"id":"riz-blanc","qty":130,"unit":"g","note":"riz jasmin, pour servir"}],"steps":["Rincez le riz jasmin puis cuisez-le avec 1,5 fois son volume d'eau, 12 min à couvert à feu doux, puis 10 min de repos hors du feu.","Dans une casserole, portez le bouillon à frémissement avec la citronnelle, le gingembre et le piment entier fendu. Laissez infuser 8 min à feu doux.","Ajoutez le lait de coco et portez juste à frémissement (ne faites pas bouillir fort, il se séparerait).","Plongez le poulet et les champignons, cuisez 8 min à petits frémissements : le poulet doit être blanc à cœur.","Ajoutez les tomates cerises 1 min, puis hors du feu la sauce poisson, le sucre et le jus des citrons verts. Goûtez : la soupe doit être à la fois acide, salée et crémeuse.","Servez avec la coriandre ciselée et un bol de riz à côté (on ne mange pas la citronnelle ni le gingembre)."],"tags":["rapide","sans gluten","riche en protéines","calorique"],"seasons":[],"technique":"mijote","flavors":["acidule","cremeux","epice"],"tips":"Remplacez le poulet par des crevettes pour un tom kha goong (3 min de cuisson seulement)."},{"id":"sa-seolleongtang","name":"Seolleongtang : bouillon d'os laiteux au jarret de bœuf","description":"Le bouillon coréen d'os de bœuf cuit si longtemps qu'il devient blanc et laiteux, servi avec de fines tranches de jarret, du riz, des oignons verts et du kimchi. Chacun sale à son goût.","emoji":"🦴","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"coreenne","prepTime":20,"cookTime":480,"restTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"os-boeuf","qty":2000,"unit":"g","note":"os à moelle et genou, sciés"},{"id":"boeuf-jarret","qty":700,"unit":"g","note":"ou poitrine de bœuf"},{"id":"eau","qty":5000,"unit":"ml"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":6,"unit":"gousse"},{"id":"gingembre","qty":15,"unit":"g"},{"id":"riz-rond","qty":340,"unit":"g","note":"riz court, cuit à part"},{"id":"oignon-nouveau","qty":4,"unit":"piece","note":"émincés"},{"id":"kimchi","qty":200,"unit":"g","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout","note":"gros sel à table"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites tremper les os et le jarret 2 h dans l'eau froide, en changeant l'eau 2 fois, pour éliminer le sang.","Blanchissez-les 10 min à gros bouillons dans une première eau, jetez cette eau et rincez les os sous l'eau froide en frottant les impuretés.","Remettez os et jarret dans un faitout propre avec 5 L d'eau, l'oignon, l'ail et le gingembre. Faites bouillir à gros bouillons (pas simple frémissement) 1 h 30, couvercle entrouvert.","Sortez le jarret, qui doit être tendre à la fourchette, et gardez-le au frais. Poursuivez l'ébullition des os 6 h en complétant avec de l'eau bouillante pour garder le niveau : c'est l'ébullition vigoureuse qui émulsionne la moelle et rend le bouillon blanc.","Filtrez le bouillon, laissez-le reposer puis retirez la graisse en surface.","Tranchez finement le jarret. Cuisez le riz (rincé, 1,2 fois son volume d'eau, 12 min à couvert puis 10 min de repos).","Servez le bouillon bouillant dans de grands bols avec les tranches de viande et les oignons verts, le riz à côté (ou plongé dedans), du gros sel, du poivre et du kimchi."],"tags":["riche en collagène","batch cooking","week-end","réconfortant","sans gluten","fermenté"],"seasons":["automne","hiver"],"technique":"bouilli","flavors":["umami","reconfortant"],"tips":"Les os peuvent faire une deuxième « fournée » de bouillon le lendemain, que l'on mélange à la première."},{"id":"sa-mercimek-kofte-agneau","name":"Mercimek çorbası et köfte d'agneau","description":"La soupe de lentilles corail turque, onctueuse, au beurre pimenté et à la menthe séchée, servie avec des köfte d'agneau grillés au cumin pour en faire un repas complet.","emoji":"🥣","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"turque","prepTime":20,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"lentilles-corail","qty":140,"unit":"g","note":"rincées"},{"id":"agneau-hache","qty":300,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"1/2 pour la soupe, 1/2 râpé pour les köfte"},{"id":"carotte","qty":1,"unit":"piece","note":"en dés"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"bouillon-volaille","qty":900,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"piment-espelette","qty":1,"unit":"cac","note":"pul biber si possible"},{"id":"cumin","qty":2,"unit":"cac"},{"id":"menthe","qty":1,"unit":"cac","note":"séchée"},{"id":"persil","qty":15,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"pain-pita","qty":2,"unit":"piece","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Rincez les lentilles corail et laissez-les tremper 2 h dans de l’eau tiède ; jetez l’eau avant de cuire.","Mélangez l'agneau avec l'oignon râpé (bien pressé), le persil haché, 1 c. à café de cumin, sel et poivre. Pétrissez 2 min puis façonnez 8 petits boudins allongés. Réservez au frais.","Dans une casserole, faites fondre 15 g de beurre à feu moyen et faites suer l'autre moitié d'oignon et la carotte 5 min. Ajoutez le concentré de tomate et le reste du cumin, remuez 1 min.","Ajoutez les lentilles et le bouillon, portez à ébullition, écumez puis cuisez 20 min à feu doux : les lentilles doivent être complètement défaites.","Pendant ce temps, faites griller les köfte dans une poêle en fonte très chaude, 3 min par face, jusqu'à ce qu'ils soient bien croûtés.","Mixez la soupe jusqu'à ce qu'elle soit parfaitement lisse ; salez, poivrez et ajoutez le jus d'un demi-citron.","Faites fondre le reste du beurre jusqu'à ce qu'il mousse, hors du feu ajoutez piment et menthe séchée. Versez ce beurre rouge en filet sur les bols de soupe et servez avec les köfte, des quartiers de citron et le pain pita chaud."],"tags":["riche en protéines","économique","réconfortant","prise de masse","préparation à l’avance"],"seasons":["automne","hiver","printemps"],"technique":"mixe","flavors":["epice","cremeux","acidule"],"tips":"La soupe seule se congèle très bien ; les köfte crus aussi, à cuire sans décongeler (5 min par face à feu moyen).","restTime":120},{"id":"sa-goulasch-leves","name":"Gulyásleves : soupe goulasch hongroise","description":"La vraie soupe goulasch des bergers hongrois : bœuf mijoté au paprika et au carvi, pommes de terre, poivrons et un bouillon rouge et fumant. Un repas complet dans le bol.","emoji":"🌶️","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"europe-centrale","prepTime":25,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-paleron","qty":800,"unit":"g","note":"en cubes de 2 cm"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"en cubes de 2 cm"},{"id":"oignon","qty":2,"unit":"piece","note":"hachés"},{"id":"poivron-rouge","qty":2,"unit":"piece","note":"en dés"},{"id":"carotte","qty":2,"unit":"piece","note":"en rondelles"},{"id":"tomate","qty":2,"unit":"piece","note":"concassées"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"graisse-canard","qty":30,"unit":"g","note":"saindoux de préférence"},{"id":"paprika","qty":3,"unit":"cas","note":"paprika doux hongrois"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"carvi"},{"id":"bouillon-boeuf","qty":1500,"unit":"ml"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"pain-seigle","qty":4,"unit":"piece","note":"tranches, pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites fondre le saindoux dans une cocotte à feu moyen. Faites revenir les oignons 8 min jusqu'à ce qu'ils soient dorés.","Montez à feu vif, ajoutez le bœuf et faites-le colorer 6 min en remuant.","Retirez la cocotte du feu, ajoutez paprika, carvi écrasé et ail haché, mélangez 30 s (le paprika brûle et devient amer à feu vif), puis versez immédiatement 500 ml de bouillon.","Remettez sur feu doux, ajoutez le laurier, couvrez et laissez mijoter 1 h : la viande doit commencer à devenir tendre.","Ajoutez le reste du bouillon, carottes, pommes de terre, poivrons et tomates. Poursuivez 35 min à frémissement, à demi couvert : les pommes de terre doivent être tendres et le bœuf fondant.","Salez, poivrez, et servez très chaud avec du pain de seigle (et un piment frais pour les amateurs)."],"tags":["mijoté","réconfortant","batch cooking","riche en protéines","familial"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","fume","reconfortant"],"tips":"Traditionnellement, on ajoute en fin de cuisson des csipetke : de petits morceaux de pâte (farine + œuf) pincés directement dans la soupe."},{"id":"sa-borscht-travers-porc","name":"Bortsch ukrainien aux travers de porc","description":"Une soupe profonde et aigre-douce : travers de porc mijotés, chou, pommes de terre et betterave en quantité modérée, finie à l'ail et à l'aneth, avec une cuillère de crème fraîche et du pain de seigle.","emoji":"🍲","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"europe-centrale","prepTime":30,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"porc-travers","qty":800,"unit":"g","note":"coupés en morceaux de 2 os"},{"id":"betterave","qty":2,"unit":"piece","note":"crues, en julienne"},{"id":"chou-vert","qty":300,"unit":"g","note":"chou blanc, émincé"},{"id":"pomme-de-terre","qty":500,"unit":"g","note":"en cubes"},{"id":"carotte","qty":1,"unit":"piece","note":"râpée"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"concentre-tomate","qty":2,"unit":"cas"},{"id":"vinaigre-cidre","qty":20,"unit":"ml"},{"id":"beurre","qty":20,"unit":"g"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"eau","qty":2500,"unit":"ml"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"aneth","qty":15,"unit":"g"},{"id":"creme-fraiche","qty":120,"unit":"ml"},{"id":"pain-seigle","qty":4,"unit":"piece","note":"tranches, pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Mettez les travers dans un faitout avec 2,5 L d'eau froide et le laurier, portez à ébullition, écumez 5 min puis laissez frémir 1 h à couvert à feu doux.","Pendant ce temps, faites fondre le beurre dans une sauteuse à feu moyen, faites suer l'oignon et la carotte 5 min, ajoutez la betterave, le concentré de tomate et le vinaigre, et cuisez 10 min en remuant : le vinaigre fixe la couleur rubis.","Ajoutez les pommes de terre au bouillon, cuisez 10 min, puis le chou et cuisez encore 10 min.","Ajoutez la poêlée de betterave et laissez mijoter 15 min à feu doux. Salez, poivrez.","Hors du feu, ajoutez l'ail râpé et la moitié de l'aneth haché, couvrez et laissez reposer 10 min : le bortsch est toujours meilleur un peu reposé.","Servez avec les travers dans chaque bol, une cuillère de crème fraîche, le reste d'aneth et le pain de seigle."],"tags":["mijoté","réconfortant","batch cooking","familial","calorique"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["acidule","sucre","reconfortant"],"tips":"Encore meilleur le lendemain. Se conserve 4 jours au réfrigérateur."},{"id":"sa-lohikeitto","name":"Lohikeitto : soupe finlandaise au saumon et à l'aneth","description":"La soupe de pêcheur finlandaise : saumon, pommes de terre et poireau dans un bouillon crémeux parfumé à l'aneth et au piment de la Jamaïque, servie avec du pain de seigle beurré.","emoji":"🐟","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"nordique","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saumon","qty":320,"unit":"g","note":"sans peau, en cubes de 3 cm"},{"id":"pomme-de-terre","qty":400,"unit":"g","note":"en cubes"},{"id":"poireau","qty":1,"unit":"piece","note":"en rondelles"},{"id":"carotte","qty":1,"unit":"piece","note":"en rondelles"},{"id":"beurre","qty":25,"unit":"g"},{"id":"fumet-poisson","qty":600,"unit":"ml"},{"id":"creme-liquide","qty":200,"unit":"ml"},{"id":"girofle","qty":1,"unit":"pincee","note":"5 baies de piment de la Jamaïque"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"aneth","qty":20,"unit":"g"},{"id":"pain-seigle","qty":2,"unit":"piece","note":"tranches beurrées, pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites fondre le beurre dans une casserole à feu moyen. Faites suer le poireau 5 min jusqu'à ce qu'il soit souple, sans coloration.","Ajoutez pommes de terre, carotte, fumet, laurier et piment de la Jamaïque. Portez à ébullition puis cuisez 15 min à feu moyen : les pommes de terre doivent être tendres.","Versez la crème, ramenez à petit frémissement.","Ajoutez le saumon et la moitié de l'aneth haché, couvrez et cuisez 5 min à feu très doux, sans remuer pour ne pas briser les cubes : le saumon doit être tout juste opaque.","Salez, poivrez, retirez le laurier. Servez parsemé du reste d'aneth, avec le pain de seigle beurré."],"tags":["rapide","riche en protéines","réconfortant","sans gluten"],"seasons":[],"technique":"poche","flavors":["cremeux","herbace","iode"],"tips":"Une version plus légère remplace la moitié de la crème par du lait entier."},{"id":"sa-cock-a-leekie","name":"Cock-a-leekie écossais aux pruneaux et à l'orge","description":"La soupe nationale écossaise : cuisses de poulet pochées avec beaucoup de poireaux, de l'orge perlé et quelques pruneaux qui apportent une douceur surprenante.","emoji":"🥣","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"britannique","prepTime":15,"cookTime":75,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":5,"unit":"piece"},{"id":"poireau","qty":4,"unit":"piece","note":"en rondelles épaisses"},{"id":"orge","qty":120,"unit":"g","note":"rincé"},{"id":"pruneaux","qty":80,"unit":"g","note":"pruneaux dénoyautés, coupés en deux"},{"id":"carotte","qty":2,"unit":"piece","note":"en dés"},{"id":"bouillon-volaille","qty":1800,"unit":"ml"},{"id":"beurre","qty":20,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"persil","qty":15,"unit":"g"},{"id":"pain-levain","qty":4,"unit":"tranche","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites tremper la céréale 12 h (une nuit) dans de l’eau tiède additionnée d’1 c. à soupe de jus de citron ou de vinaigre de cidre. Rincez avant de cuire.","Mettez les cuisses de poulet dans un faitout avec le bouillon, le thym et le laurier. Portez à frémissement, écumez 5 min, puis cuisez 40 min à feu doux.","Pendant ce temps, faites fondre le beurre dans une poêle et faites suer le vert des poireaux 5 min à feu moyen.","Sortez les cuisses, laissez tiédir 10 min, puis retirez la peau et effilochez la chair en gros morceaux. Remettez les os dans le bouillon.","Ajoutez au bouillon l'orge et les carottes, cuisez 25 min à frémissement : l'orge doit être tendre mais encore un peu ferme.","Retirez les os, ajoutez tous les poireaux (le blanc cru et le vert fondu), les pruneaux et le poulet effiloché. Cuisez 10 min de plus.","Salez, poivrez, parsemez de persil haché et servez avec le pain."],"tags":["réconfortant","familial","batch cooking","économique","riche en protéines","préparation à l’avance"],"seasons":["automne","hiver","printemps"],"technique":"poche","flavors":["reconfortant","sucre","herbace"],"tips":"Les pruneaux sont traditionnels mais facultatifs ; ils se marient très bien avec le poireau.","restTime":720},{"id":"sa-veloute-celeri-moelle-saint-jacques","name":"Velouté de céleri-rave, moelle rôtie et Saint-Jacques","description":"Un velouté d'hiver très doux de céleri-rave au beurre, servi avec des noix de Saint-Jacques snackées et des tartines de moelle rôtie à la fleur de sel. Un dîner de fête simple.","emoji":"🦪","category":"soupe","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":35,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"celeri-rave","qty":600,"unit":"g","note":"épluché, en cubes"},{"id":"pomme-de-terre","qty":1,"unit":"piece"},{"id":"saint-jacques","qty":12,"unit":"piece","note":"noix sans corail, bien sèches"},{"id":"os-a-moelle","qty":2,"unit":"piece","note":"tronçons de 6 à 8 cm, dégorgés 1 nuit"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"beurre","qty":40,"unit":"g"},{"id":"bouillon-volaille","qty":600,"unit":"ml"},{"id":"lait","qty":200,"unit":"ml"},{"id":"pain-levain","qty":4,"unit":"tranche"},{"id":"persil","qty":10,"unit":"g"},{"id":"noisette","qty":20,"unit":"g","note":"torréfiées, concassées","optional":true},{"id":"sel","qty":1,"unit":"au-gout","note":"et fleur de sel"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites fondre 20 g de beurre dans une casserole à feu moyen, faites suer l'échalote 3 min, ajoutez le céleri et la pomme de terre, remuez 2 min.","Versez bouillon et lait, portez à frémissement et cuisez 25 min à feu doux : le céleri doit s'écraser facilement.","Pendant ce temps, préchauffez le four à 220 °C. Posez les os à moelle debout sur une plaque, salez et rôtissez 18 à 20 min : la moelle doit être translucide, tremblotante et commencer à se détacher de l'os.","Mixez le velouté avec 10 g de beurre 2 min jusqu'à ce qu'il soit très lisse et brillant. Salez, poivrez ; maintenez au chaud.","Toastez le pain. Chauffez une poêle à feu vif avec le reste du beurre jusqu'à ce qu'il mousse ; saisissez les Saint-Jacques 1 min 30 par face sans les bouger : elles doivent être dorées dessus et nacrées à cœur.","Servez le velouté dans des assiettes creuses avec 6 Saint-Jacques par personne, les noisettes et le persil. À côté, chacun étale la moelle à la cuillère sur son pain grillé et la parsème de fleur de sel."],"tags":["week-end","abats","riche en protéines","riche en collagène","four"],"seasons":["automne","hiver"],"technique":"mixe","flavors":["cremeux","iode","umami"],"tips":"Pour dégorger la moelle, laissez les os 12 h dans de l'eau froide salée au réfrigérateur en changeant l'eau 2 fois."}]`);export{e as default};